// Task studio-subway-architecture-materials-rework-20261117-072826-01 (lane TEX): the Subway architecture rework's Codex PBR surface sets.
//  - files: every SUBWAY_ARCH_TEXTURES map is in game/public with the generated bytes and an allowlist entry (bytes / sha256), a
//    1024 x 1024 JPEG; every set's provenance names its Codex ledger call / session / source sha and the output shas, with no URL,
//    local path or prompt text;
//  - measurements: spans plausible (0.3-3.5 m) and whole multiples of the declared joint module (within 10 %); mean albedo / roughness;
//  - ownership: textures/subway/** is Subway-only (assets/levelAssets.ts);
//  - runtime (world/subwayArchTextures.ts): the stand-in (no maps, mean x tint), the mapped world-mapped PBR material once the maps are
//    registered, thin variants (anisotropy-1 map clones), the per-name cache and the section preload (level key, colour spaces).
import {afterAll, describe, expect, it} from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {fileURLToPath} from 'node:url';
import * as THREE from 'three';
import {installCanvasShim} from './helpers/canvas2d';
import {fakeEnvTextures} from './helpers/openablesFixture';
import {SUBWAY_ARCH_TEXTURES, type SubwayArchTexKey} from '../src/assets/subwayArchTextures.generated';
import {assetAllowedIn, levelOfAsset} from '../src/assets/levelAssets';
import {WorldMaterials, isWorldMapped} from '../src/world/materials';
import {DECAY_PROFILES} from '../src/world/decay';
import {reflectTagOf} from '../src/render/reflectTag';
import {SUBWAY_ARCH_KEYS, SubwayArchTextures, installSubwayArchTextures, setSubwayArchTexture, subwayArchMaterial, subwayArchTexture, type SubwayArchMap} from '../src/world/subwayArchTextures';
import type {StationLayout} from '../src/gen/stationTypes';

installCanvasShim(false);

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const MAPS: readonly SubwayArchMap[] = ['color', 'normal', 'orm'];
const sha = (b: Buffer) => crypto.createHash('sha256').update(b).digest('hex');
const allow = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/release/public-inputs.json'), 'utf8')) as {files: {path: string; bytes: number; sha256: string}[]};
const allowOf = new Map(allow.files.map(f => [f.path, f]));
/** Joint module (m per repeat of the joint pattern) per axis as the prompts declare it; null = jointless (stochastic / slats along). */
const MODULE: Readonly<Record<SubwayArchTexKey, readonly [number | null, number | null]>> = {
  tileCream: [0.15, 0.15], tileBlueSquare: [0.15, 0.15], tileGreenBrick: [0.2, 0.15], tileTerracotta: [0.2, 0.2], tileWhiteLarge: [0.3, 0.15],
  bandOxblood: [0.15, 0.15], bandNavy: [0.15, 0.15], bandBottle: [0.15, 0.15], bandOchre: [0.15, 0.15], bandSignal: [0.15, 0.15], bandOrange: [0.15, 0.15],
  plinthGranite: [0.6, 0.3], stoneLimestone: [1.2, 0.6], concretePrecast: [1.2, 1.2], enamelPanel: [1.2, 0.6], metalSlatCeiling: [0.115, null],
  floorTerrazzo: [0.6, 0.6], floorGranite: [0.6, 0.6], ceilingPlaster: [null, null], rockPainted: [null, null],
};
/** Width / height of a baseline or progressive JPEG (its SOF segment). */
function jpegSize(b: Buffer): [number, number] {
  for (let i = 2; i + 9 < b.length;) {
    if (b[i] !== 0xff) { i++; continue; }
    const m = b[i + 1];
    if (m === 0xc0 || m === 0xc1 || m === 0xc2) return [b.readUInt16BE(i + 7), b.readUInt16BE(i + 5)];
    i += 2 + b.readUInt16BE(i + 2);
  }
  return [0, 0];
}
const clearRegistry = () => { for (const k of SUBWAY_ARCH_KEYS) for (const m of MAPS) setSubwayArchTexture(k, m, null); };
afterAll(clearRegistry);

describe('Subway architecture sets: files, allowlist, provenance', () => {
  it('lists the twenty sets of the rework', () => {
    expect(SUBWAY_ARCH_KEYS.sort()).toEqual(Object.keys(MODULE).sort());
  });

  it.each(SUBWAY_ARCH_KEYS)('%s: maps present with the generated bytes, allowlisted, 1024 x 1024 JPEG', key => {
    const set = SUBWAY_ARCH_TEXTURES[key];
    for (const m of MAPS) {
      const f = set[m];
      expect(f.url.startsWith('/')).toBe(false);
      expect(f.url).toMatch(/^assets\/textures\/subway\/arch\/subway-arch-[a-z-]+-(?:color|normal|orm)\.jpg$/);
      const buf = fs.readFileSync(path.join(ROOT, 'game/public', f.url));
      expect(buf.length, f.url).toBe(f.bytes);
      const row = allowOf.get(f.url);
      expect(row, f.url).toBeTruthy();
      expect(row!.bytes).toBe(buf.length);
      expect(row!.sha256).toBe(sha(buf));
      expect(jpegSize(buf), f.url).toEqual([1024, 1024]);
    }
  });

  it.each(SUBWAY_ARCH_KEYS)('%s: provenance names the Codex call, session, source and outputs; no URL / local path / prompt text', key => {
    const set = SUBWAY_ARCH_TEXTURES[key];
    const name = /subway-arch-([a-z-]+)-color\.jpg$/.exec(set.color.url)![1];
    const rel = `assets/derivatives/subway-arch-${name}.json`;
    const text = fs.readFileSync(path.join(ROOT, 'game/public', rel), 'utf8');
    const row = allowOf.get(rel);
    expect(row, rel).toBeTruthy();
    expect(row!.sha256).toBe(sha(Buffer.from(text)));
    expect(text).not.toMatch(/https?:|\/home\/|\/workspaces\/|~\/|token=|Signature=|api[_-]?key/i);
    const p = JSON.parse(text);
    expect(p.schema).toBe('last-line-derivative/1');
    expect(p.generator).toMatch(/Codex native image_gen/);
    expect(Number.isInteger(p.codex.ledgerCall) && p.codex.ledgerCall > 0).toBe(true);
    expect(p.codex.session).toMatch(/^[0-9a-f-]{36}$/);
    expect(p.source.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(p.source.file).toMatch(new RegExp(`^codex-${p.codex.ledgerCall}-${name}-exec-[0-9a-f-]+\\.png$`));
    expect(Object.keys(p.prompt).sort()).toEqual(['file', 'sha256']);
    expect(p.prompt.sha256).toMatch(/^[0-9a-f]{64}$/);
    expect(p.status).toMatch(/no licence or commercial clearance implied/);
    for (const m of MAPS) {
      expect(p.outputs[m].url).toBe(set[m].url);
      expect(p.outputs[m].sha256).toBe(sha(fs.readFileSync(path.join(ROOT, 'game/public', set[m].url))));
    }
    expect([p.spanM.u, p.spanM.v]).toEqual([...set.span]);
    expect(p.meanLinearAlbedo).toEqual([...set.mean]);
    expect(p.cls).toBe(set.cls);
  });

  it('the CREDITS section names every set', () => {
    const credits = fs.readFileSync(path.join(ROOT, 'game/public/assets/CREDITS.md'), 'utf8');
    const sec = /<!-- BEGIN subway-arch-20261117[^>]*-->([\s\S]*?)<!-- END subway-arch-20261117 -->/.exec(credits)?.[1] ?? '';
    expect(sec).toMatch(/Codex native image generation/);
    expect(sec).toMatch(/no licence or commercial clearance implied/);
    for (const k of SUBWAY_ARCH_KEYS) expect(sec).toContain(/subway-arch-([a-z-]+)-color/.exec(SUBWAY_ARCH_TEXTURES[k].color.url)![1]);
    const row = allowOf.get('assets/CREDITS.md');
    expect(row!.sha256).toBe(sha(Buffer.from(credits)));
  });
});

describe('Subway architecture sets: measured scale and finish', () => {
  it.each(SUBWAY_ARCH_KEYS)('%s: span plausible and a whole number of joint modules; mean albedo and roughness sane', key => {
    const set = SUBWAY_ARCH_TEXTURES[key];
    set.span.forEach((s, a) => {
      expect(s, `${key} ${a}`).toBeGreaterThanOrEqual(0.3);
      expect(s, `${key} ${a}`).toBeLessThanOrEqual(3.5);
      const mod = MODULE[key][a];
      if (mod === null) return;
      const n = Math.max(1, Math.round(s / mod));
      expect(Math.abs(s - n * mod), `${key} axis ${a}: ${s} m vs ${n} x ${mod} m`).toBeLessThanOrEqual(0.1 * mod);
    });
    // linear mean: luminance in (0.02, 0.85), every channel <= 0.85 (saturated glazes may hold one channel near 0.015)
    const lum = 0.2126 * set.mean[0] + 0.7152 * set.mean[1] + 0.0722 * set.mean[2];
    expect(lum).toBeGreaterThan(0.02);
    expect(lum).toBeLessThan(0.85);
    for (const c of set.mean) { expect(c).toBeGreaterThan(0); expect(c).toBeLessThanOrEqual(0.85); }
    expect(set.rough).toBeGreaterThan(0.15);
    expect(set.rough).toBeLessThan(0.96);
  });

  it('class finishes: glazed tile glossier than stone, stone than concrete / plaster / rock', () => {
    const mean = (cls: string) => { const v = SUBWAY_ARCH_KEYS.filter(k => SUBWAY_ARCH_TEXTURES[k].cls === cls).map(k => SUBWAY_ARCH_TEXTURES[k].rough); return v.reduce((a, b) => a + b, 0) / v.length; };
    expect(mean('tile')).toBeLessThan(0.35);
    expect(mean('tile')).toBeLessThan(mean('stone'));
    for (const c of ['concrete', 'plaster', 'rock']) expect(mean('stone')).toBeLessThan(mean(c));
  });
});

describe('ownership: textures/subway/** is Subway-only', () => {
  it('every set file belongs to the Subway and no other level may load it', () => {
    for (const k of SUBWAY_ARCH_KEYS) for (const m of MAPS) {
      const u = SUBWAY_ARCH_TEXTURES[k][m].url;
      expect(levelOfAsset(u), u).toBe('subway');
      expect(assetAllowedIn('subway', u), u).toBe(true);
      for (const other of ['mall', 'office', 'reactor', 'skyways', 'market', 'bunker', 'surface']) expect(assetAllowedIn(other, u), `${other} ${u}`).toBe(false);
    }
    // the Subway's existing allowance for the Reactor family's mine-rock / pit-concrete sets is unchanged
    expect(assetAllowedIn('subway', 'assets/textures/reactor/mine-rock-color.jpg')).toBe(true);
    expect(assetAllowedIn('subway', 'assets/textures/reactor/rusted-steel-color.jpg')).toBe(false);
  });
});

describe('runtime: world/subwayArchTextures.ts', () => {
  const fake = (aniso: number) => { const t = new THREE.Texture({width: 16, height: 16} as unknown as HTMLImageElement); t.anisotropy = aniso; return t; };
  const look = {role: 'wall' as const, reflect: 'gloss' as const, tint: [1.1, 0.9, 0.8] as const, grime: [0.3, 1.2] as [number, number], macro: 0.2, normal: 1.4, roughness: 0.9, decay: DECAY_PROFILES.tileUpper};

  it('stand-in without maps (mean x tint), then the mapped world-mapped PBR material once registered; cached per name', () => {
    clearRegistry();
    const mats = new WorldMaterials(fakeEnvTextures(), 7, {w: 1.2, h: 0.19, d: 0.17});
    const key: SubwayArchTexKey = 'tileCream', set = SUBWAY_ARCH_TEXTURES[key];
    const s = subwayArchMaterial(mats, key, 'test-cream', look);
    expect(s.map).toBeNull();
    expect(s.normalMap).toBeNull();
    expect(s.color.r).toBeCloseTo(set.mean[0] * 1.1, 5);
    expect(s.color.g).toBeCloseTo(set.mean[1] * 0.9, 5);
    expect(s.color.b).toBeCloseTo(set.mean[2] * 0.8, 5);
    expect(s.roughness).toBeCloseTo(set.rough * 0.9, 5);
    expect(s.userData.lightAlbedo).toEqual([Math.min(0.8, set.mean[0] * 1.1), Math.min(0.8, set.mean[1] * 0.9), Math.min(0.8, set.mean[2] * 0.8)]);
    expect(s.userData.subwayArchTex).toBe(key);
    expect(isWorldMapped(s)).toBe(true);
    expect(s.wmMap.x).toBeCloseTo(1 / set.span[0], 6);
    expect(s.wmMap.y).toBeCloseTo(1 / set.span[1], 6);
    expect(s.userData.decay).toEqual(DECAY_PROFILES.tileUpper);
    expect(reflectTagOf(s)).toBe('gloss');
    expect(subwayArchMaterial(mats, key, 'test-cream', look)).toBe(s);
    // a JSON-safe userData: a clone of the finish (the finish mapper's tinted copies) works
    expect(() => s.clone()).not.toThrow();

    const tex = {color: fake(8), normal: fake(4), orm: fake(4)};
    for (const m of MAPS) setSubwayArchTexture(key, m, tex[m]);
    expect(subwayArchTexture(key, 'orm')).toBe(tex.orm);
    const t = subwayArchMaterial(mats, key, 'test-cream', look);
    expect(t).not.toBe(s);
    expect(t.map).toBe(tex.color);
    expect(t.normalMap).toBe(tex.normal);
    expect(t.roughnessMap).toBe(tex.orm);
    expect(t.metalnessMap).toBe(tex.orm);
    expect(t.normalScale.x).toBeCloseTo(1.4, 6);
    expect(t.roughness).toBeCloseTo(0.9, 6);
    expect([t.color.r, t.color.g, t.color.b].map(v => +v.toFixed(5))).toEqual([1.1, 0.9, 0.8]);
    expect(t.userData.lightAlbedo).toEqual(s.userData.lightAlbedo);
    expect(t.userData.subwayArchTex).toBe(key);
    expect(isWorldMapped(t)).toBe(true);
    expect(reflectTagOf(t)).toBe('gloss');
    expect(t.userData.decay).toEqual(DECAY_PROFILES.tileUpper);
    expect(tex.color.anisotropy).toBe(16); // a wall surface asks for the surface anisotropy (render/anisotropy.ts)
    expect(subwayArchMaterial(mats, key, 'test-cream', look)).toBe(t);
    // another WorldMaterials: its own material
    const mats2 = new WorldMaterials(fakeEnvTextures(), 8, {w: 1.2, h: 0.19, d: 0.17});
    expect(subwayArchMaterial(mats2, key, 'test-cream', look)).not.toBe(t);
    clearRegistry();
  });

  it('thin variants sample anisotropy-1 clones of the shared maps', () => {
    clearRegistry();
    const mats = new WorldMaterials(fakeEnvTextures(), 7, {w: 1.2, h: 0.19, d: 0.17});
    const tex = {color: fake(8), normal: fake(4), orm: fake(4)};
    for (const m of MAPS) setSubwayArchTexture('plinthGranite', m, tex[m]);
    const m = subwayArchMaterial(mats, 'plinthGranite', 'test-plinth-thin', {role: 'trim', reflect: 'none', thin: true});
    for (const k of ['map', 'normalMap', 'roughnessMap', 'metalnessMap'] as const) {
      expect(m[k], k).toBeTruthy();
      expect(m[k]!.anisotropy, k).toBe(1);
    }
    expect(m.map).not.toBe(tex.color);
    expect(tex.color.anisotropy).toBe(8); // the shared maps are untouched
    expect(reflectTagOf(m)).toBe('none');
    expect(m.userData.decay).toBeUndefined();
    expect(subwayArchMaterial(mats, 'plinthGranite', 'test-plinth-thin', {role: 'trim', reflect: 'none', thin: true})).toBe(m);
    clearRegistry();
  });

  it('the section preload: the Subway level key, colour sRGB, data linear; failures leave stand-ins; no sets = registry cleared', async () => {
    clearRegistry();
    const asked: {level: string; url: string; srgb: boolean; anisotropy?: number}[] = [];
    const host = {sectionPreloads: [] as ((l: StationLayout) => Promise<void>)[], levelResources: {load: (level: string, url: string, spec: {srgb: boolean; repeat: boolean; anisotropy?: number}) => {
      asked.push({level, url, srgb: spec.srgb, anisotropy: spec.anisotropy});
      expect(spec.repeat).toBe(true);
      return url.includes('rock-painted-normal') ? Promise.reject(new Error('offline')) : Promise.resolve(new THREE.Texture());
    }}};
    let want: SubwayArchTexKey[] = ['tileCream', 'rockPainted', 'tileCream'];
    const rt = installSubwayArchTextures(host, () => want);
    expect(rt).toBeInstanceOf(SubwayArchTextures);
    expect(host.sectionPreloads).toHaveLength(1);
    await host.sectionPreloads[0]({} as StationLayout);
    expect(asked.map(a => a.url).sort()).toEqual(['tileCream', 'rockPainted'].flatMap(k => MAPS.map(m => SUBWAY_ARCH_TEXTURES[k as SubwayArchTexKey][m].url)).sort());
    for (const a of asked) {
      expect(a.level).toBe('subway');
      expect(assetAllowedIn(a.level, a.url)).toBe(true);
      expect(a.srgb, a.url).toBe(a.url.endsWith('-color.jpg'));
      expect(a.anisotropy, a.url).toBe(a.url.endsWith('-color.jpg') ? 8 : 4);
    }
    expect(rt.counts).toEqual({loaded: 5, missing: 1});
    expect(subwayArchTexture('tileCream', 'color')).not.toBeNull();
    expect(subwayArchTexture('rockPainted', 'normal')).toBeNull();
    expect(subwayArchTexture('floorTerrazzo', 'color')).toBeNull();
    // a layout without sets: nothing fetched, the previous level's maps unregistered
    want = [];
    asked.length = 0;
    await host.sectionPreloads[0]({} as StationLayout);
    expect(asked).toEqual([]);
    expect(subwayArchTexture('tileCream', 'color')).toBeNull();
  });
});
